package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeFactory_rawClass_TriageGen2Test {

    /**
     * Test case where the input is a direct Class object.
     * This covers the first branch: if (t instanceof Class<?>)
     */
    @Test
    public void testRawClass_WithClassInstance() {
        Class<String> input = String.class;
        Class<?> result = TypeFactory.rawClass(input);
        assertSame("Should return the same class instance when input is a Class", input, result);
    }

    /**
     * Test case where the input is a ParameterizedType (e.g., List<String>).
     * This covers the second branch: defaultInstance().constructType(t).getRawClass()
     */
    @Test
    public void testRawClass_WithParameterizedType() throws Exception {
        Type type = new TypeReference<List<String>>() {}.getType();
        // Verify it is indeed a ParameterizedType
        assertTrue(type instanceof ParameterizedType);

        Class<?> result = TypeFactory.rawClass(type);
        assertEquals("Should extract the raw class (List) from the parameterized type", List.class, result);
    }

    /**
     * Test case where the input is an ArrayType.
     */
    @Test
    public void testRawClass_WithArrayType() throws Exception {
        Type type = String[].class.getGenericSuperclass(); // Or similar
        // Using a more direct way to get a GenericArrayType
        Type arrayType = String[].class.getTypeParameters()[0].getAnnotatedType(); 
        // Simpler: use a TypeReference for an array
        Type arrayRef = new TypeReference<String[]>() {}.getType();

        Class<?> result = TypeFactory.rawClass(arrayRef);
        assertEquals("Should return the component type class or array class appropriately", String[].class, result);
    }

    /**
     * Test case where the input is a WildcardType.
     */
    @Test
    public void testRawClass_WithWildcardType() throws Exception {
        // Creating a wildcard type: List<? extends Number>
        Type wildcardType = new TypeReference<List<? extends Number>>() {}.getType();

        Class<?> result = TypeFactory.rawClass(wildcardType);
        assertEquals("Should return the raw class of the collection containing the wildcard", List.class, result);
    }

    /**
     * Test case with a complex nested type.
     */
    @Test
    public void testRawClass_WithNestedParameterizedType() throws Exception {
        // Type: Map<String, List<Integer>>
        Type nestedType = new TypeReference<Map<String, List<Integer>>>() {}.getType();

        Class<?> result = TypeFactory.rawClass(nestedType);
        assertEquals("Should return the outermost raw class", Map.class, result);
    }

    /**
     * Test case where the input is a TypeVariable.
     * Note: The behavior of constructType on a raw TypeVariable depends on the TypeFactory context,
     * but generally it should resolve to the bound or the variable's representation.
     */
    @Test
    public void testRawClass_WithTypeVariable() throws Exception {
        class TestClass<T> {}
        TypeVariable<T> typeVariable = TestClass.class.getTypeParameters()[0];

        // TypeFactory.rawClass(typeVariable)
        Class<?> result = TypeFactory.rawClass(typeVariable);
        // Depending on Jackson version, this might return Object.class or the bound.
        // We check that it doesn't throw an exception and returns a valid Class.
        assertNotNull(result);
    }
}
